/* Cities the sky map can be shown on: any place on Earth.
 * Three cities are hand-tuned (real neighbourhood anchors). Every other city, featured or searched, is
 * generated by makeCity(): the six abstract districts from data.js are laid out around the city centre, and
 * geo.js later swaps their directional names ("North Paris") for real ones from OpenStreetMap. */
window.ES = window.ES || {};

ES.DESIGN_CENTER = { x: 600, y: 360 };
ES.GENERIC_METERS_PER_UNIT = 8;

const handTuned = (id, name, country, cc, lat, lng, metersPerUnit, hoods) =>
  ({ id, name, country, cc, lat, lng, metersPerUnit, hoods, named: true });

ES.CITIES = {
  london: handTuned('london', 'London', 'United Kingdom', 'GB', 51.5072, -0.1276, 9, {
    northgate: { name: 'Camden',      lat: 51.5390, lng: -0.1426 },
    oldmarket: { name: 'Clerkenwell', lat: 51.5235, lng: -0.1055 },
    eastfield: { name: 'Hackney',     lat: 51.5450, lng: -0.0553 },
    riverside: { name: 'Chelsea',     lat: 51.4875, lng: -0.1687 },
    southpark: { name: 'Peckham',     lat: 51.4740, lng: -0.0690 },
    harbor:    { name: 'Brixton',     lat: 51.4613, lng: -0.1156 },
  }),
  newyork: handTuned('newyork', 'New York', 'United States', 'US', 40.7580, -73.9855, 5.5, {
    northgate: { name: 'Harlem',          lat: 40.8116, lng: -73.9465 },
    oldmarket: { name: 'Midtown',         lat: 40.7549, lng: -73.9840 },
    eastfield: { name: 'Astoria',         lat: 40.7644, lng: -73.9235 },
    riverside: { name: 'West Village',    lat: 40.7358, lng: -74.0036 },
    southpark: { name: 'Williamsburg',    lat: 40.7081, lng: -73.9571 },
    harbor:    { name: 'Lower Manhattan', lat: 40.7075, lng: -74.0113 },
  }),
  mumbai: handTuned('mumbai', 'Mumbai', 'India', 'IN', 19.0330, 72.8500, 6.5, {
    northgate: { name: 'Bandra',  lat: 19.0596, lng: 72.8365 },
    oldmarket: { name: 'Dadar',   lat: 19.0178, lng: 72.8478 },
    eastfield: { name: 'Kurla',   lat: 19.0726, lng: 72.8845 },
    riverside: { name: 'Worli',   lat: 19.0060, lng: 72.8195 },
    southpark: { name: 'Sewri',   lat: 18.9984, lng: 72.8573 },
    harbor:    { name: 'Byculla', lat: 18.9790, lng: 72.8330 },
  }),
};

/** One per continent-ish, so the world view starts out as a real global constellation. */
ES.FEATURED_PLACES = [
  ['Tokyo', 'Japan', 'JP', 35.6812, 139.7671], ['Paris', 'France', 'FR', 48.8566, 2.3522],
  ['São Paulo', 'Brazil', 'BR', -23.5505, -46.6333], ['Lagos', 'Nigeria', 'NG', 6.5244, 3.3792],
  ['Sydney', 'Australia', 'AU', -33.8830, 151.2000], ['Delhi', 'India', 'IN', 28.6139, 77.2090],
  ['Nairobi', 'Kenya', 'KE', -1.2864, 36.8172], ['Mexico City', 'Mexico', 'MX', 19.4326, -99.1332],
  ['Cairo', 'Egypt', 'EG', 30.0444, 31.2357], ['Singapore', 'Singapore', 'SG', 1.3400, 103.8300],
  ['Berlin', 'Germany', 'DE', 52.5200, 13.4050], ['Toronto', 'Canada', 'CA', 43.6700, -79.3900],
  ['Los Angeles', 'United States', 'US', 34.0522, -118.2437], ['Jakarta', 'Indonesia', 'ID', -6.2088, 106.8456],
  ['Buenos Aires', 'Argentina', 'AR', -34.6037, -58.3816], ['Dubai', 'United Arab Emirates', 'AE', 25.2048, 55.2708],
].map(([name, country, cc, lat, lng]) => ({ name, country, cc, lat, lng }));

const DIRECTIONAL = {
  northgate: (c) => `Northwest ${c}`, oldmarket: (c) => `Central ${c}`, eastfield: (c) => `Northeast ${c}`,
  riverside: (c) => `West ${c}`, southpark: (c) => `Southeast ${c}`, harbor: (c) => `South ${c}`,
};

const offsetLatLng = (lat, lng, dxMeters, dyMeters) => ({
  lat: lat - dyMeters / 111320,
  lng: lng + dxMeters / (111320 * Math.cos((lat * Math.PI) / 180)),
});

ES.cityId = (place) => `${place.name}-${place.cc || place.country || ''}-${place.lat.toFixed(2)}`
  .normalize('NFKD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9.-]+/g, '-');

/** Build a city from any geocoded place: { name, country, cc, lat, lng }. */
ES.makeCity = (place) => {
  const m = ES.GENERIC_METERS_PER_UNIT;
  const hoods = Object.fromEntries(ES.HOODS_BASE.map((h) => {
    const p = offsetLatLng(place.lat, place.lng, (h.x - ES.DESIGN_CENTER.x) * m, (h.y - ES.DESIGN_CENTER.y) * m);
    return [h.id, { name: DIRECTIONAL[h.id](place.name), lat: p.lat, lng: p.lng }];
  }));
  return {
    id: ES.cityId(place), name: place.name, country: place.country || '', cc: (place.cc || '').toUpperCase(),
    lat: place.lat, lng: place.lng, metersPerUnit: m, hoods, named: false,
  };
};

ES.FEATURED_PLACES.forEach((p) => { const c = ES.makeCity(p); ES.CITIES[c.id] = c; });

ES.DEFAULT_CITY = 'london';

/** Flag image for an ISO country code. Images, not emoji: Windows doesn't render flag emoji. */
ES.flag = (cc) => (/^[A-Z]{2}$/.test(cc || '')
  ? `<img class="flag" src="https://flagcdn.com/w40/${cc.toLowerCase()}.png" alt="" width="20" height="15" loading="lazy">`
  : '<span class="flag">🌐</span>');

/** Great-circle distance in km between two { lat, lng } points. */
ES.distKm = (a, b) => {
  const r = Math.PI / 180;
  const h = Math.sin(((b.lat - a.lat) * r) / 2) ** 2
    + Math.cos(a.lat * r) * Math.cos(b.lat * r) * Math.sin(((b.lng - a.lng) * r) / 2) ** 2;
  return 12742 * Math.asin(Math.sqrt(h));
};

/** Abstract star (x, y in the 1200×720 design space) → real [lat, lng] in the given city. */
ES.project = (star, city) => {
  if (Number.isFinite(star.lat) && Number.isFinite(star.lng)) return [star.lat, star.lng]; // real places (backend)
  const base = ES.HOODS_BASE.find((h) => h.id === star.hood);
  const anchor = city.hoods[star.hood] || Object.values(city.hoods)[0];
  const dx = base ? star.x - base.x : 0;
  const dy = base ? star.y - base.y : 0;
  const p = offsetLatLng(anchor.lat, anchor.lng, dx * city.metersPerUnit, dy * city.metersPerUnit);
  return [p.lat, p.lng];
};
